definition.script:
@NonCPS
def parseJarName(String jarFileName) {
    def matcher = jarFileName =~ /^(.*)-(\d+\.\d+\.\d+)-SNAPSHOT\.jar$/
    if (matcher.matches()) {
        return [matcher[0][1], matcher[0][2]]
    }
    return null
}

def testResultsProps = ""

pipeline{
    agent{
        label "build-agent"
    }
    tools {
        jfrog "my-jfrog-cli"
        gradle "my-gradle"
    }
    environment {
        GIT_REPO_URL = "http://gitlab:13000/my-hands-on-group/webapp-webui.git"
        JAR_FILE_PATTERN = "build/libs/apisl.handson.rollingdice.webapp.webui-*-SNAPSHOT.jar"
        ARTIFACTORY_REPO = "hands-on-rollingdice-webapp-webui"
        ARTIFACTORY_VIRTUAL_REPO = "gradle-virtual"
        SBOM_FILE_PATH = "build/reports/application.cdx.json"
        UNIT_TEST_RESULT_DIR = "build/test-results/test"
        UNIT_TEST_RESULT_EXT = "*.xml"
        UNIT_TEST_COVERAGE_PATH = "build/reports/jacoco/test/jacocoTestReport.xml"
        SPOT_BUGS_RESULT_PATTERN = "build/reports/spotbugs/*.xml"
        PMD_RESULT_PATTERN = "build/reports/pmd/*.xml"
        CHECK_STYLE_RESULT_PATTERN = "build/reports/checkstyle/*.xml"
        JAVADOC_DIR = "build/docs/javadoc"
        DEPENDENCY_TRACK_API_KEY_ID = "dependency-track-api-key"
    }
    stages{
//        stage("Clean up a local environment"){
//            steps{
//                echo "### START: clean up the cloned directoy"
//                deleteDir()
//            }
//        }
        stage("Checkout a repository from GitLab"){
            steps{
               echo "### START: clone a repository from GitLab"
               git branch: "main", url: "${env.GIT_REPO_URL}"
            }
        }
        stage('Build a repository with JFrog CLI') {
            steps {
                echo "### START: build with jfrog cli"
                jf "gradle-config --repo-deploy ${ARTIFACTORY_REPO} --repo-resolve ${ARTIFACTORY_VIRTUAL_REPO}"
                jf "gradle assemble -x cyclonedxBom --info --build-name=${ARTIFACTORY_REPO} --build-number=${BUILD_NUMBER}"
            }
        }
        stage("Generate SBOM") {
            steps {
                echo "### START: generate SBOM using CycloneDX plugin"
                jf "gradle cyclonedxBom --info --build-name=${ARTIFACTORY_REPO} --build-number=${BUILD_NUMBER}"
            }
        }
        stage('Publish SBOM to Dependency-Track') {
            steps {
                echo "### START: publich SBOM to Dependency-Track"
                script {
                    // 1. Get the full path of the JAR files that match a pattern.
                    def jarFilePath = sh(script: "find . -path './${env.JAR_FILE_PATTERN}'", returnStdout: true).trim()
                    if (jarFilePath.isEmpty()) {
                        error "JAR file not found with pattern: ${env.JAR_FILE_PATTERN}"
                    }

                    // 2. Extract only the file name from the full path.
                    def jarFileName = sh(script: "basename '${jarFilePath}'", returnStdout: true).trim()
                    echo "Found JAR file: ${jarFileName}"

                    // 3. Extract project name and version using regular expressions.
                    def projectInfo = parseJarName(jarFileName)
                    if (projectInfo == null) {
                        error "Could not parse project name and version from JAR file: ${jarFileName}"
                    }

                    def parsedProjectName = projectInfo[0]
                    def parsedProjectVersion = projectInfo[1]
                    echo "Parsed Project Name: ${parsedProjectName}"
                    echo "Parsed Project Version: ${parsedProjectVersion}"

                    withCredentials([string(credentialsId: "${env.DEPENDENCY_TRACK_API_KEY_ID}", variable: 'API_KEY')]) {
                        dependencyTrackPublisher artifact: "${env.SBOM_FILE_PATH}",
                            projectName: parsedProjectName,
                            projectVersion: parsedProjectVersion,
                            synchronous: true,
                            dependencyTrackApiKey: API_KEY
                    }
                }
            }
            post {
                success {
                    archiveArtifacts artifacts: "${env.SBOM_FILE_PATH}", allowEmptyArchive: true
                }
            }
        }
        stage("Run Unit Tests"){
            steps{
                echo "### START: run unit tests"
                jf "gradle test -x cyclonedxBom --info --build-name=${ARTIFACTORY_REPO} --build-number=${BUILD_NUMBER}"
            }
            post {
                always {
                    junit "${env.UNIT_TEST_RESULT_DIR}/${env.UNIT_TEST_RESULT_EXT}"
                    script {
                        try {
                            def totalTests = 0
                            def failedTests = 0
                            def erroredTests = 0
                            def skippedTests = 0

                            def testFilesOutput = sh(script: "find ${env.UNIT_TEST_RESULT_DIR} -name '${env.UNIT_TEST_RESULT_EXT}'", returnStdout: true).trim()

                            if (testFilesOutput.isEmpty()) {
                                echo "No JUnit test result files found."
                                testResultsProps = "tests.status=no-results"
                            } else {
                                def testFiles = testFilesOutput.split("\\n")
                                testFiles.each { filePath ->
                                    if (fileExists(filePath)) {
                                        // extract all necessary attribute values from the testsuite tag using the awk command
                                        // get as a comma-separated string in the order "tests,failures,errors,skipped"
                                        def awkCommand = "awk -F'\"' '/<testsuite/ {for(i=1;i<=NF;i++){if(\$i~/tests=\$/){t=\$(i+1)} if(\$i~/failures=\$/){f=\$(i+1)} if(\$i~/errors=\$/){e=\$(i+1)} if(\$i~/skipped=\$/){s=\$(i+1)}} printf \"%d,%d,%d,%d\", t, f, e, s}'"
                                        def countsStr = sh(script: "${awkCommand} '${filePath}'", returnStdout: true).trim()

                                        def counts = countsStr.split(",")
                                        if (counts.size() == 4) {
                                            totalTests += counts[0].toInteger()
                                            failedTests += counts[1].toInteger() // failures
                                            erroredTests += counts[2].toInteger() // errors
                                            skippedTests += counts[3].toInteger()
                                        }
                                    }
                                }

                                def passedTests = totalTests - failedTests - erroredTests - skippedTests
                                testResultsProps = "tests.total=${totalTests};tests.passed=${passedTests};tests.failed=${failedTests};tests.errored=${erroredTests};tests.skipped=${skippedTests}"
                                echo "Generated test result properties for Artifactory: ${testResultsProps}"
                            }
                        } catch (e) {
                            echo "Could not parse JUnit test results. Skipping property attachment. Error: ${e.message}"
                            testResultsProps = "tests.status=unavailable"
                        }
                    }
                }
            }
        }
        stage("Analyze test codes coverage"){
            steps{
                echo "### START: analyze a test code coverage"
                jf "gradle jacocoTestReport -x cyclonedxBom --info --build-name=${ARTIFACTORY_REPO} --build-number=${BUILD_NUMBER}"
            }
            post {
                always {
                    recordCoverage(
                        tools: [[parser: "JACOCO", pattern: "${env.UNIT_TEST_COVERAGE_PATH}"]],
                        id: "jacoco", name: "JaCoCo Coverage",
                        sourceCodeRetention: "EVERY_BUILD",
                        qualityGates: [
                            [threshold: 60.0, metric: "LINE", baseline: "PROJECT", unstable: true],
                            [threshold: 60.0, metric: "BRANCH", baseline: "PROJECT", unstable: true]]
                    )
                }
            }
        }
        stage("Analyze binaries with SpotBugs"){
            steps{
                echo "### START: analyze binaries with spotbugs"
                jf "gradle spotbugsMain spotbugsTest -x cyclonedxBom --info --build-name=${ARTIFACTORY_REPO} --build-number=${BUILD_NUMBER}"
            }
            post {
                always {
                    recordIssues tools: [
                        spotBugs(pattern: "${env.SPOT_BUGS_RESULT_PATTERN}")
                    ]
                }
            }
        }
        stage("Analyze codes with PMD"){
            steps{
                echo "### START: analyze codes with pmd"
                jf "gradle pmdMain pmdTest -x cyclonedxBom --info --build-name=${ARTIFACTORY_REPO} --build-number=${BUILD_NUMBER}"
            }
            post {
                always {
                    recordIssues tools: [
                        pmdParser(pattern: "${env.PMD_RESULT_PATTERN}")
                    ]
                }
            }
        }
        stage("Analyze codes with Checkstyle"){
            steps{
                echo "### START: analyze codes with checkstyle"
                jf "gradle checkstyleMain checkstyleTest -x cyclonedxBom --info --build-name=${ARTIFACTORY_REPO} --build-number=${BUILD_NUMBER}"
            }
            post {
                always {
                    recordIssues tools: [
                        checkStyle(pattern: "${env.CHECK_STYLE_RESULT_PATTERN}")
                    ]
                }
            }
        }
        stage("Generate a Javadoc") {
            steps {
                echo "### START: generate a javadoc"
                jf "gradle javadoc -x cyclonedxBom --info --build-name=${ARTIFACTORY_REPO} --build-number=${BUILD_NUMBER}"
            }
            post {
                always {
                    echo "### START: publish a javadoc using javadoc plugin"
                    javadoc javadocDir: "${env.JAVADOC_DIR}", keepAll: true
                }
            }
        }
        stage("Release an artifact to Artifactory") {
            steps {
                echo "### START: release an artifact to artifactory"
                script {
                    def props = "build.name=${ARTIFACTORY_REPO};build.number=${BUILD_NUMBER};${testResultsProps}"
                    def spec = """{
                        "files": [
                            {
                                "pattern": "${JAR_FILE_PATTERN}",
                                "target": "${ARTIFACTORY_REPO}",
                                "props": "${props}"
                            }
                        ]
                    }"""
                    writeFile file: "upload.spec", text: spec
                    jf "rt u --spec=upload.spec"
                }
            }
        }
        stage("Publish a build info to Artifactory") {
            steps {
                echo "### START: publish a build info to Artifactory"
                jf "rt build-publish ${ARTIFACTORY_REPO} ${BUILD_NUMBER}"
            }
        }
    }
    post{
        always{
            echo "========always========"
        }
        success{
            echo "========pipeline executed successfully ========"
        }
        failure{
            echo "========pipeline execution failed========"
        }
    }
}
